package android.util;import java.io.*;import java.nio.file.*;public class AtomicFile{public static boolean dropNextCommit=false;private final File file;private final File pending;public AtomicFile(File f){file=f;pending=new File(f+".new");}public File getBaseFile(){return file;}public FileInputStream openRead()throws IOException{return new FileInputStream(file);}public FileOutputStream startWrite()throws IOException{file.getParentFile().mkdirs();return new FileOutputStream(pending);}public void finishWrite(FileOutputStream s){try{s.close();if(dropNextCommit){dropNextCommit=false;return;}Files.move(pending.toPath(),file.toPath(),StandardCopyOption.REPLACE_EXISTING);}catch(IOException e){throw new IllegalStateException(e);}}public void failWrite(FileOutputStream s){try{s.close();}catch(IOException e){}pending.delete();}}